<title>Login Page</title>
<style>
.login-header {
    text-align: center;
    margin-bottom: 10px;
}
.login-form {
    margin-bottom: 20px;
}
.login-input {
    padding: 10px;
    border: 1px solid #ccc;
    border-radius: 5px;
}
#login-button {
    padding: 10px 20px;
    background-color: #4CAF50;
    color: #fff;
